-- Real data reconstructed from the Hautel Company Drive, 28 Sep 2026 (dataset = 'real').
-- Sources per row: 'Research & Development/WP1 - Architecture & Data Foundation/Real data (Drive)/'.
-- Requires migration 004. Idempotent on the fixed ids; documents are keyed by (property/org, title).
begin;
on conflict (id) do update set name=excluded.name, kind=excluded.kind, dataset='real';
on conflict (id) do update set org_id=excluded.org_id, name=excluded.name, region=excluded.region, dataset='real';
on conflict (property_id) do update set segment=excluded.segment, audience=excluded.audience, positioning=excluded.positioning, channels=excluded.channels, strengths=excluded.strengths, weaknesses=excluded.weaknesses, updated_at=now();
on conflict (id) do update set email=excluded.email, full_name=excluded.full_name;
on conflict do nothing;
on conflict (id) do update set title=excluded.title, description=excluded.description, category=excluded.category, urgency=excluded.urgency, budget_band=excluded.budget_band, dataset='real';
delete from documents where source like 'drive/%';
commit;
