insert into hotel_profiles (property_id, segment, audience, positioning, channels, strengths, weaknesses) values
  ('e2000000-0000-0000-0000-000000000001','boutique','International leisure and business guests in Antwerp; locals and event guests for Sapphire Patio (F&B). Multi-language markets: EN, NL, DE, ES.','Premium heritage boutique hotel in the centre of Antwerp, run within Odyssey Hotel Group standards; wants a consistent, recognisable visual language and a proactive digital partner acting as an extension of the internal marketing team.','{instagram,linkedin,meta_ads,google_ads,google_business,ota,website}','{heritage building,f&b (Sapphire Patio),group backing (OHG),existing Hautel content partnership}','{no dedicated social & digital agency,inconsistent social output,multi-brand copy in EN/NL/DE/ES,paid media and Google Ads not managed}'),
  ('e2000000-0000-0000-0000-000000000002','business','Airport and corporate travellers, conference groups.','Pandox-owned airport hotel; in the 2026 annual report it carries the ''hotel life'' story: reception, lobby, breakfast and F&B in morning light.','{ota,google_ads,linkedin}','{airport location,F&B and breakfast,Pandox ESG programme}','{brand awareness beyond airport traffic}'),
  ('e2000000-0000-0000-0000-000000000003','boutique','Design-led city travellers; Pandox annual-report audience for people and DEI themes.','IHG boutique hotel; annual-report themes are human rights, DEI and well-being: housekeeping in action, sustainable cleaning products, team diversity, Vajra/Varga/BIGH sourcing.','{instagram,linkedin,ota}','{design identity,engaged housekeeping and F&B teams,sustainability sourcing partners}','{limited own content capacity}'),
  ('e2000000-0000-0000-0000-000000000004','business','Event planners and corporate MICE buyers first; international leisure travellers second.','Le Palace, opened 1910, DoubleTree by Hilton since renovation; with the new wing (ballroom, breakout rooms, Pagoda) it becomes Belgium''s second-largest hotel and a major conference destination. Brand claim ''The Little Things Mean Everything''; C.A.R.E. culture; signature cookie. Wants to reposition from older perceptions to a living-heritage conference hotel: cinematic, contemporary, never generic corporate.','{website,youtube,linkedin,instagram,corporate_screens}','{1910 heritage architecture and Art Deco details,new ballroom and conference ecosystem,central Brussels location,newly opened restaurant (Grand Cafe 1909),bowl-concept conference catering}','{markets still hold outdated perceptions,previous hotel videos felt generic,F&B availability limits during shoots}'),
  ('e2000000-0000-0000-0000-000000000005','business','Business and leisure guests at a landmark Grand Place property; annual-report audience for guest experience and smart operations.','Landmark Hilton; annual-report themes are guest experience, inclusive culture and smart operations: BMS/Sensorea, Climato, solar panels, Too Good To Go, Enozo cleaning, Hope & Glory teas.','{ota,linkedin,google_ads}','{landmark location,engineering and sustainability story,front office hospitality}','{technical story hard to make visual}'),
  ('e2000000-0000-0000-0000-000000000006','luxury','Quiet-luxury leisure and business guests; spa on the 25th floor with Brussels panorama.','Pandox flagship for well-being and quiet luxury; annual-report themes: spa serenity, wellness details, architecture, BREEAM, AI tools in-room. Preferred location for the Code of Conduct video.','{website,instagram,ota}','{25th-floor spa and panorama,architecture,quiet-luxury positioning}','{no explicit weaknesses documented}'),
  ('e2000000-0000-0000-0000-000000000007','boutique','Young urban guests and short-stay professionals in Ghent; social, advertising and OTA audiences.','New RAIBU apart-hotel in Ghent: ''from the chaos of the city to the calm inside''; Japanese-minimal warm interiors, keyless check-in; lifestyle experience, not a hotel tour. Look: VHS texture meets clean digital.','{instagram,tiktok,meta_ads,ota}','{design-led interiors,digital-first guest journey,brand family (STAY-C)}','{new location with no content library,styling and set dressing must come from STAY-C}'),
  ('e2000000-0000-0000-0000-000000000008','business','Investors, partners, B2B sales, recruitment and web audiences of a fast-growing operator.','STAY-C: hospitality operator founded 2020, six brands (A-STAY, RAIBU, ROMY, PATTY, JACKEY, XEPA), 1000+ units in Belgium and 300+ in pipeline; develops concepts, manages operations, builds brands; digital-first ecosystem (keyless check-in, AI guest comms, dynamic pricing, owner portal).','{linkedin,website,sales_decks}','{scale and pipeline,distinct brand identities under one operational standard,technology stack}','{no corporate film or reusable content library yet}'),
  ('e2000000-0000-0000-0000-000000000009','resort','Loyal older clientele today; target younger active couples for direct bookings; FR-speaking primary, EN and NL secondary.','Cocoon Hotel La Rive: renovated four-star riverside hotel on the Sure at Bourscheid-Plage (Luxembourg): 19 rooms, 12 cottage suites, a villa, health centre with sauna and hammam, riverside restaurant. Perceived as a quiet destination for seniors; wants to be seen as an oasis of nature, wellness and fine dining lived at two tempos.','{website,ota,google_business,instagram,tiktok,brochure}','{nature and river setting,cottages and villa,wellness (sauna, hammam, treatments),fine dining,loyal returning guests}','{perception gap with younger couples,voucher- and package-driven clientele,no models or confirmed guest filming consent,outdated website imagery}')
